test.config:
searchd
{

	postings_format = block
}

source src
{
	type = xmlpipe2
	xmlpipe_command = cat /data.xml
}

index plain_default
{
	source = src
	path = /plain_default
}

index plain_legacy : plain_default
{
	path = /plain_legacy
	postings_format = legacy
}

index inherited_legacy : plain_legacy
{
	path = /inherited_legacy
}

index rt_default
{
	type = rt
	path = /rt_default
	rt_field = body
}

index rt_legacy : rt_default
{
	path = /rt_legacy
	postings_format = legacy
}

queries.sphinxql:
SHOW TABLE plain_default SETTINGS;
SHOW TABLE plain_legacy SETTINGS;
SHOW TABLE inherited_legacy SETTINGS;
SHOW TABLE rt_default SETTINGS;
SHOW TABLE rt_legacy SETTINGS;
SELECT id FROM plain_default WHERE MATCH('hello') ORDER BY id ASC;
SELECT id FROM plain_legacy WHERE MATCH('hello') ORDER BY id ASC;
SELECT id FROM inherited_legacy WHERE MATCH('hello') ORDER BY id ASC;
INSERT INTO rt_default VALUES (1,'hello world');
INSERT INTO rt_legacy VALUES (1,'hello world');
FLUSH RAMCHUNK rt_default;
FLUSH RAMCHUNK rt_legacy;
SELECT id FROM rt_default WHERE MATCH('hello');
SELECT id FROM rt_legacy WHERE MATCH('hello');
